import{_ as t,a as d,o,a6 as r}from"./chunks/framework.CJDy2q7X.js";const u=JSON.parse('{"title":"Add-Product Search (Create-Order)","description":"","frontmatter":{"outline":false,"apiType":"rest","examples":[{"id":"admin-products-list","title":"Add-Product Search (Create-Order)","description":"The slim product search behind the admin Create-Order \\"Add Product\\" modal. Not the product listing — for the full datagrid with every column and filter use List Products. Returns all statuses by default, so disabled and draft products appear.","query":"curl -X GET \\"https://your-domain.com/api/admin/products?sku=SP-001&type=simple&per_page=30&page=1\\" \\\\\\n  -H \\"Accept: application/json\\" \\\\\\n  -H \\"Authorization: Bearer <id>|<token>\\"\\n","variables":"sku=SP-001&type=simple&per_page=30&page=1\\n","response":"{\\n  \\"data\\": [\\n    {\\n      \\"id\\": 2512,\\n      \\"sku\\": \\"SP-001\\",\\n      \\"type\\": \\"simple\\",\\n      \\"name\\": \\"Arctic Cozy Knit Unisex Beanie\\",\\n      \\"status\\": 1,\\n      \\"price\\": 14,\\n      \\"formattedPrice\\": \\"$14.00\\",\\n      \\"baseImageUrl\\": \\"http://localhost:8000/cache/medium/product/2512/Muc0qeWks34MTZaxf38s6DBmfqMqrCxku81Uo8EB.webp\\",\\n      \\"isSaleable\\": true\\n    }\\n  ],\\n  \\"meta\\": {\\n    \\"currentPage\\": 1,\\n    \\"perPage\\": 30,\\n    \\"lastPage\\": 1,\\n    \\"total\\": 1,\\n    \\"from\\": 1,\\n    \\"to\\": 1\\n  }\\n}\\n","commonErrors":[{"error":"Unauthenticated (401)","cause":"Missing, malformed, expired, or revoked admin Bearer token","solution":"Send a valid admin Bearer token (Integration token) in the Authorization header. See the Authentication page."}]},{"id":"admin-products-search","title":"Free-Text Search","description":"The `query` parameter matches SKU or product name partially, which is what the modal\'s search box sends as the admin types.","query":"curl -X GET \\"https://your-domain.com/api/admin/products?query=beanie&per_page=10\\" \\\\\\n  -H \\"Accept: application/json\\" \\\\\\n  -H \\"Authorization: Bearer <id>|<token>\\"\\n","variables":"query=beanie&per_page=10\\n","response":"{\\n  \\"data\\": [\\n    {\\n      \\"id\\": 2512,\\n      \\"sku\\": \\"SP-001\\",\\n      \\"type\\": \\"simple\\",\\n      \\"name\\": \\"Arctic Cozy Knit Unisex Beanie\\",\\n      \\"status\\": 1,\\n      \\"price\\": 14,\\n      \\"formattedPrice\\": \\"$14.00\\",\\n      \\"baseImageUrl\\": \\"http://localhost:8000/cache/medium/product/2512/Muc0qeWks34MTZaxf38s6DBmfqMqrCxku81Uo8EB.webp\\",\\n      \\"isSaleable\\": true\\n    }\\n  ],\\n  \\"meta\\": {\\n    \\"currentPage\\": 1,\\n    \\"perPage\\": 10,\\n    \\"lastPage\\": 1,\\n    \\"total\\": 1,\\n    \\"from\\": 1,\\n    \\"to\\": 1\\n  }\\n}\\n"}]},"headers":[],"relativePath":"api/rest-api/admin/catalog/products/list.md","filePath":"api/rest-api/admin/catalog/products/list.md","lastUpdated":1787725411000}'),a={name:"api/rest-api/admin/catalog/products/list.md"};function n(c,e,i,s,l,p){return o(),d("div",null,e[0]||(e[0]=[r('<h1 id="add-product-search-create-order" tabindex="-1">Add-Product Search (Create-Order) <a class="header-anchor" href="#add-product-search-create-order" aria-label="Permalink to &quot;Add-Product Search (Create-Order)&quot;">​</a></h1><p>The slim product <strong>search</strong> behind the admin <strong>Create Order</strong> screen&#39;s &quot;Add Product&quot; modal. It answers one question — which product is the admin picking? — and returns just enough to render a picker row.</p><p>This is not the product listing. For the full admin datagrid, with every column and the Channel / Name / SKU / Attribute Family / Price / ID / Status / Type filters, use <a href="/api/rest-api/admin/catalog/products.html">List Products</a> (<code>GET /api/admin/catalog/products</code>). This page covers only the Create-Order picker.</p><h2 id="endpoint" tabindex="-1">Endpoint <a class="header-anchor" href="#endpoint" aria-label="Permalink to &quot;Endpoint&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Endpoint</th><th>Method</th></tr></thead><tbody><tr><td><code>/api/admin/products</code></td><td>GET</td></tr></tbody></table><p>Results come back in the <code>{ data, meta }</code> envelope used by every admin collection.</p><h2 id="query-parameters" tabindex="-1">Query Parameters <a class="header-anchor" href="#query-parameters" aria-label="Permalink to &quot;Query Parameters&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>page</code></td><td>integer</td><td>Page number, default <code>1</code>.</td></tr><tr><td><code>per_page</code></td><td>integer</td><td>Items per page, default <code>30</code>, capped at <code>50</code>.</td></tr><tr><td><code>query</code></td><td>string</td><td>Free text — partial match against SKU <strong>or</strong> product name.</td></tr><tr><td><code>sku</code></td><td>string</td><td>Exact SKU.</td></tr><tr><td><code>type</code></td><td>string</td><td><code>simple</code>, <code>configurable</code>, <code>bundle</code>, <code>downloadable</code>, <code>grouped</code>, <code>virtual</code>, or <code>booking</code>.</td></tr><tr><td><code>status</code></td><td>integer</td><td><code>0</code> disabled, <code>1</code> enabled. Omit to get both.</td></tr><tr><td><code>categoryId</code></td><td>integer</td><td>Restrict to products in one category.</td></tr><tr><td><code>channel</code></td><td>string</td><td>Channel code used to resolve <code>name</code> and <code>price</code>.</td></tr><tr><td><code>locale</code></td><td>string</td><td>Locale code used to resolve <code>name</code>.</td></tr><tr><td><code>sort</code></td><td>string</td><td><code>id</code>, <code>sku</code>, <code>created_at</code>, or <code>updated_at</code>.</td></tr><tr><td><code>order</code></td><td>string</td><td><code>asc</code> or <code>desc</code>. Defaults to <code>desc</code>.</td></tr></tbody></table><p>Parameters combine with AND — each one you add narrows the result. <code>query</code> and <code>sku</code> are separate: <code>query</code> is the partial &quot;as you type&quot; match, <code>sku</code> is exact.</p><p>Note the page size here is <code>30</code>, not the <code>10</code> used by every other admin collection — the picker is built to show a long scroll list.</p><h2 id="row-shape" tabindex="-1">Row Shape <a class="header-anchor" href="#row-shape" aria-label="Permalink to &quot;Row Shape&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>integer</td><td>Numeric product id — the value to send when adding the item to a cart.</td></tr><tr><td><code>sku</code></td><td>string</td><td>Product SKU.</td></tr><tr><td><code>type</code></td><td>string</td><td>Product type.</td></tr><tr><td><code>name</code></td><td>string|null</td><td>Resolved for the requested channel and locale.</td></tr><tr><td><code>status</code></td><td>integer|null</td><td><code>1</code> enabled, <code>0</code> disabled.</td></tr><tr><td><code>price</code></td><td>number|null</td><td>Minimal price for the product.</td></tr><tr><td><code>formattedPrice</code></td><td>string|null</td><td>The same price rendered in the channel currency.</td></tr><tr><td><code>baseImageUrl</code></td><td>string</td><td>Medium-size image URL, falling back to the theme placeholder when the product has no image.</td></tr><tr><td><code>isSaleable</code></td><td>boolean</td><td>Whether the product can currently be sold.</td></tr></tbody></table><p>The row is deliberately nine fields — no variants, bundle options, images array, or attribute values. Use <a href="/api/rest-api/admin/catalog/products/products-detail.html">Product Detail</a> once a product is picked.</p><p>Two fields behave unlike their counterparts elsewhere:</p><ul><li><strong><code>baseImageUrl</code> is never null.</strong> A product without an image gets the theme&#39;s placeholder URL, so an &quot;is there an image?&quot; check on this field always says yes.</li><li><strong><code>name</code> and <code>status</code> can both be <code>null</code></strong> for a product created through the API but never completed in step two — the picker still lists it. Fall back to <code>sku</code> for the display label.</li></ul><h2 id="how-it-differs-from-api-shop-products" tabindex="-1">How It Differs From <code>/api/shop/products</code> <a class="header-anchor" href="#how-it-differs-from-api-shop-products" aria-label="Permalink to &quot;How It Differs From `/api/shop/products`&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>Shop</th><th>Admin</th></tr></thead><tbody><tr><td>Default status filter</td><td>Only <code>status = 1</code> and <code>visible_individually = 1</code></td><td>None — every status returned</td></tr><tr><td>Booking products</td><td>Hidden by storefront visibility rules</td><td>Listed, but blocked when added to a draft cart</td></tr><tr><td>Row payload</td><td>Full storefront product</td><td>Nine fields</td></tr><tr><td>Pagination</td><td>Response headers (<code>X-Total-Count</code>, <code>X-Page</code>, …)</td><td>Body envelope (<code>{ data, meta }</code>) — no pagination headers</td></tr><tr><td>Authentication</td><td>Storefront key, plus an optional customer token</td><td>Admin Bearer token</td></tr></tbody></table><h2 id="booking-products" tabindex="-1">Booking Products <a class="header-anchor" href="#booking-products" aria-label="Permalink to &quot;Booking Products&quot;">​</a></h2><p>Booking products are returned so the admin can find them, but adding one to a draft cart via <code>POST /api/admin/carts/{id}/items</code> fails with HTTP <code>400</code> and &quot;Booking products cannot be added to an admin draft order.&quot; This mirrors the admin panel, whose Create-Order screen ships no booking form.</p><h2 id="errors" tabindex="-1">Errors <a class="header-anchor" href="#errors" aria-label="Permalink to &quot;Errors&quot;">​</a></h2><p>Requires an admin Bearer token. There is no separate permission gate on the search itself.</p>',21)]))}const m=t(a,[["render",n]]);export{u as __pageData,m as default};
